/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-button {display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 36px; padding: 8px 14px; border: 1px solid var(--line); border-radius: 7px; background: var(--surface); color: var(--ink); font-size: 12px; line-height: 1.3; font-weight: 500; text-decoration: none; white-space: nowrap;}
.ds-button:hover {background: var(--canvas); border-color: color-mix(in srgb, var(--ink) 25%, var(--line));}
.ds-button-disabled, .ds-button:disabled, .ds-button[aria-disabled="true"] {opacity: .5; cursor: not-allowed; pointer-events: none;}
.ds-button-primary {background: var(--accent); border-color: transparent; color: var(--accent-ink);}
.ds-button-primary:hover {background: var(--accent-hover); border-color: transparent;}
.ds-button {font-family:"Red Hat Text", ui-sans-serif, sans-serif;transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, box-shadow 160ms ease-out;}
.ds-button:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-button { transition-duration: .01ms; } }

