/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-input, .ds-select, .ds-textarea {width: 100%; min-height: 39px; padding: 9px 11px; background: var(--surface); color: var(--ink); border: 1px solid var(--line); border-radius: 7px; font-size: 13px; line-height: 1.5;}
.ds-input::placeholder, .ds-textarea::placeholder {color: var(--muted); opacity: 1;}
.ds-input:focus, .ds-select:focus, .ds-textarea:focus {border-color: var(--accent); outline: 2px solid color-mix(in srgb, var(--accent) 18%, transparent); outline-offset: 1px;}
.ds-input:disabled, .ds-select:disabled, .ds-textarea:disabled {opacity: .6; background: var(--canvas);}
.ds-input-error, .ds-select-error, .ds-textarea-error {border-color: var(--error);}
.ds-field {display: block; margin-bottom: 16px;}
.ds-label {display: flex; align-items: center; gap: 9px; margin-bottom: 7px; color: var(--ink); font-size: 12px; font-weight: 500;}
.ds-field {font-family:"Red Hat Text", ui-sans-serif, sans-serif;} .ds-input {font-family:inherit;transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, box-shadow 160ms ease-out;}
.ds-input:focus-visible {border-color: var(--accent); outline: 2px solid color-mix(in srgb, var(--accent) 18%, transparent); outline-offset: 1px;}
@media (prefers-reduced-motion: reduce) { .ds-input { transition-duration: .01ms; } }

/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-nav-link {display: flex; align-items: center; gap: 11px; margin: 3px 0; padding: 10px 12px; border-radius: 7px; color: var(--sidebar-ink); font-size: 12px;}
.ds-nav-link:hover {color: #fff; background: #ffffff09;}
.ds-nav-link[aria-current="page"] {background: #d7f8e514; color: #baf0d1;}
.ds-active-dot {display: none; width: 5px; height: 5px; margin-left: auto; border-radius: 50%; background: #a4e9bf;}
.ds-nav-link[aria-current="page"] .ds-active-dot {display: block;}
.ds-navigation {padding:12px;max-width:240px;background:var(--sidebar);font-family:"Red Hat Text", ui-sans-serif, sans-serif;} .ds-nav-link {text-decoration:none;transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, box-shadow 160ms ease-out;}
.ds-nav-link:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-nav-link { transition-duration: .01ms; } }
.ds-nav-link svg {width:17px;height:17px;flex-shrink:0;color:var(--sidebar-muted);} .ds-nav-link[aria-current="page"] svg {color:#baf0d1;}

/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-badge {display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 5px; background: var(--canvas); color: var(--muted); font-size: 11px; font-weight: 500; line-height: 1.5; white-space: nowrap;}
.ds-badge-primary, .ds-badge-success {background: var(--accent-soft); color: var(--success);}
.ds-badge {font-family:"Red Hat Text", ui-sans-serif, sans-serif;}
.ds-badge:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-badge { transition-duration: .01ms; } }

/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-panel {min-width: 0; background: var(--surface); border: 1px solid var(--line); border-radius: 12px;}
.ds-panel-body {padding: 24px;}
.ds-panel-title {font-size: 16px; font-weight: 600;}
.ds-panel {color:var(--ink);font-family:"Red Hat Text", ui-sans-serif, sans-serif;} .ds-panel-title {margin:0;} .ds-panel-copy {font-size:13px;line-height:1.55;color:var(--muted);margin:7px 0 0;}
.ds-panel:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-panel { transition-duration: .01ms; } }

/* Source: assets/css/app.css; inherited semantic variables support both light and dark themes. */
.ds-table {width: 100%; border-collapse: collapse; text-align: left; font-size: 12px; background: var(--surface);}
.ds-table th {padding: 12px 16px; background: var(--canvas); color: var(--muted); font-size: 11px; font-weight: 500; white-space: nowrap; border-bottom: 1px solid var(--line);}
.ds-table td {padding: 13px 16px; border-bottom: 1px solid var(--line); vertical-align: middle;}
.ds-table tbody tr:last-child td {border-bottom: 0;}
.ds-table tbody tr:hover {background: color-mix(in srgb, var(--accent) 3%, var(--surface));}
.ds-table-frame {width: 100%; overflow-x: auto; border: 1px solid var(--line); border-radius: 12px; background: var(--surface);}
.ds-table td, .ds-table th {padding: 10px 12px;}
.ds-table {color:var(--ink);font-family:"Red Hat Text", ui-sans-serif, sans-serif;font-variant-numeric:tabular-nums;}
.ds-table-frame:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-table-frame { transition-duration: .01ms; } }

/* Source: assets/css/app.css and bundled Heroicons 16px solid SVGs; inherited semantic variables support both light and dark themes. */
.ds-theme-switcher {display: inline-flex; padding: 3px; border: 1px solid var(--line); border-radius: 7px; background: var(--canvas);}
.ds-theme-switcher button {display: grid; place-items: center; width: 27px; height: 25px; border-radius: 4px; color: var(--muted);}
.ds-theme-switcher button:hover {color: var(--ink);}
.ds-theme-switcher button[aria-pressed="true"] {background: var(--surface); color: var(--accent); box-shadow: 0 1px 3px #00000012;}
.ds-theme-switcher button {border:0;padding:0;cursor:pointer;transition: background-color 160ms ease-out, color 160ms ease-out;} .ds-theme-switcher svg {width:14px;height:14px;}
.ds-theme-switcher button:focus-visible {outline: 2px solid var(--focus); outline-offset: 3px;}
@media (prefers-reduced-motion: reduce) { .ds-theme-switcher button { transition-duration: .01ms; } }
